-- Question sets: existing questions become set 1; 150 new questions added as sets 2-4 (50 each).
-- Run once. Student tests are drawn across all sets (see pickQuestions in server/logic.js).
alter table questions add column if not exists question_set int not null default 1;
create index if not exists questions_question_set_idx on questions(question_set);
insert into questions(text,options,correct_option_id,question_set) values
